(15303,'Virtual assistant for new medical practice',22,'Title: Virtual Assistant for Medical Practice\r\n\r\nLocation: Remote\r\n\r\nJob Type: Contract\r\n\r\nOverview:\r\n\r\nNew medical practice seeking a virtual assistant to join our team. The ideal candidate will have excellent communication skills, strong attention to detail, and ability to multitask.  The virtual assistant will be responsible for managing administrative and clerical tasks to ensure the medical practice runs smoothly.\r\n\r\nResponsibilities:\r\n\r\n- Answering calls and responding to texts in a timely manner\r\n- Maintaining patient records and updating electronic medical records\r\n- Coordinating with insurance companies for claims and billing\r\n- Managing inventory and ordering supplies as needed\r\n- Providing excellent customer service to patients and their families\r\n- Performing other administrative tasks as required\r\n\r\nRequirements:\r\n\r\n- High school diploma or equivalent\r\n- Prior experience as a virtual assistant in a medical practice preferred\r\n- Excellent communication and interpersonal skills\r\n- Strong attention to detail and organizational skills\r\n- Ability to multitask and prioritize tasks effectively\r\n- Proficiency in Microsoft Office and electronic medical records software\r\n- Ability to maintain confidentiality and handle sensitive information with discretion','https://www.upwork.com/jobs/~01011ab5669bf1d76e','-',7,'United States','US',11.940,'Open this select menu',18.000,'2023-03-26',1,'2023-03-26',1,'normal bidding',0,'Open this select menu',NULL,1,'2023-03-26 17:51:16',NULL,12,3,NULL,157),
(15304,'Billing specialist',21,'Generates revenue by making payment arrangements, collecting accounts, and monitoring and pursuing delinquent accounts.\r\nCollects delinquent accounts by establishing payment arrangements with patients, monitoring payments, and following up with patients when payment lapses occur.\r\nUtilizes collection agencies and small claims court to collect accounts by evaluating and selecting collection agencies, determines appropriateness of pursuing legal remedies, and testifies in court cases.\r\nMaintains Medicare bad-debt cost report by tracking billings, monitoring collections, and compiling information.\r\nInitiates claims against estates by monitoring deaths and unpaid accounts, informing legal department to act on probate and estate issues, and following-up with clerk of court.\r\nSecures outstanding balance payments for care of employees by establishing payroll deductions and obtaining signatures for automatic transfers.\r\nSecures obstetrical payments by interviewing and obtaining information from pre-delivery patients, establishing payments due prior to delivery and sending monthly statements.\r\nMaintains work operations by following policies and procedures, and reporting compliance issues.\r\nMaintains quality results by following standards.\r\nProtects clinic’s/hospital’s value by keeping collection information confidential.\r\nUpdates job knowledge by participating in educational opportunities.\r\nServes and protects the clinical community by adhering to professional standards, hospital or clinic policies and procedures, federal, state, and local requirements and standards.\r\nEnhances billing department and practice reputation by accepting ownership for accomplishing new and different requests and exploring opportunities to add value to job accomplishments.','https://www.upwork.com/jobs/~01f99106f66ae0d68b','-',7,'United States','Pakistan',25.000,'Open this select menu',18.000,'2023-03-26',1,'2023-03-26',1,'normal bidding',0,'Open this select menu',NULL,1,'2023-03-26 17:53:04',NULL,12,3,NULL,157),
